def same_shape(s: str, t: str) -> bool:
    # Record what each character becomes, in both directions; stop at the first conflict.
    return False

solution:
def same_shape(s: str, t: str) -> bool:
    forward, backward = {}, {}          # s-char -> t-char, t-char -> s-char
    for a, b in zip(s, t):
        if forward.setdefault(a, b) != b or backward.setdefault(b, a) != a:
            return False
    return True

perf.naive:
def same_shape(s: str, t: str) -> bool:
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n):          # every pair of positions
            if (s[i] == s[j]) != (t[i] == t[j]):
                return False
    return True
